import csv
from collections import defaultdict

with open('/app/dataset/hospital_compensation_registry.csv') as f:
    rows = list(csv.DictReader(f))

# full scoring
patient_has_claim = {}
for r in rows:
    pid = r['patient_id']
    if r['record_date'].strip():
        patient_has_claim[pid] = True
for r in rows:
    pid = r['patient_id']
    if pid not in patient_has_claim:
        patient_has_claim[pid] = False

ec_of_count = defaultdict(int)
for r in rows:
    ec = r['emergency_contact_patient_id']
    if ec:
        ec_of_count[ec] += 1

no_claim_set = set(k for k,v in patient_has_claim.items() if not v)

cands = []
for pid in no_claim_set:
    # get their info
    rlist = [x for x in rows if x['patient_id'] == pid]
    if not rlist: continue
    r = rlist[0]
    ec = r['emergency_contact_patient_id']
    # get EC claims
    ec_claims = []
    for rr in rows:
        if rr['patient_id'] == ec and rr['record_date'].strip():
            ec_claims.append(rr)
    score = 0
    reasons = [c['compensation_reason'] for c in ec_claims]
    serious = {'bereavement compensation', 'life event claim', 'family support adjustment'}
    trauma = {'vehicle crash injury', 'workplace fall injury', 'burn injury'}
    if any(cr in serious for cr in reasons):
        score += 10  # very strong signal
    elif any(cr in trauma for cr in reasons):
        score += 3
    # also if EC has many claims and this patient has no claims - maybe
    score += len(ec_claims) * 0.5
    score += ec_of_count.get(pid, 0) * 0.3
    # no claims themselves is implicit
    cands.append((pid, score, ec, reasons))

cands.sort(key=lambda x: x[1], reverse=True)
for c in cands[:10]:
    print(c)
